-- JumRok starter content: the homestay catalogue and blog posts.
--
-- Run AFTER schema.sql, in the Supabase Dashboard: SQL Editor > New query >
-- paste > Run. Safe to re-run: existing rows are updated in place.
--
-- These rows have no host_id/author_id — they belong to the platform, not to
-- a host account — and go straight in as 'approved' so the site has content
-- from day one. The SQL Editor bypasses RLS, which is what allows that.

-- ---- Listings --------------------------------------------------------------
insert into public.listings (
  id, status, host_id, name, tagline, description, images, thumbnail_url, region, area, category, tags, price_amount, price_currency, price_unit, rating_score, review_count, max_guests, beds, room_type, room_size_value, room_size_unit, facilities, experiences, host_name, host_avatar_url, reviewed_at
)
values
  ('preah-village-homestay', 'approved', null, 'Preah Village Homestay', 'Local meals · Village life', 'Stay with a welcoming family in a traditional wooden stilt house on the outskirts of Siem Reap. Share home-cooked Khmer meals and evening stories on the veranda.', array['https://images.unsplash.com/photo-1628194968194-5189a8b51909?auto=format&fit=crop&w=1600&q=82', 'https://images.unsplash.com/photo-1634623391440-eee532636511?auto=format&fit=crop&w=1600&q=82', 'https://images.unsplash.com/photo-1672833474987-d50e626b7f3d?auto=format&fit=crop&w=1600&q=82']::text[], 'https://images.unsplash.com/photo-1628194968194-5189a8b51909?auto=format&fit=crop&w=800&q=80', 'Siem Reap', 'Angkor Countryside', 'Village Homestay', array['Rural & Countryside', 'Family-run']::text[], 18, 'USD', 'night', 4.7, 41, 3, 2, 'Private stilt house room', 18, 'sqm', array['WiFi', 'Parking', 'Fan', 'Shared bathroom']::text[], array['Home-cooked meals', 'Village walk', 'Traditional weaving demo']::text[], 'Sokha Ven', 'https://images.example.com/hosts/sokha-ven.jpg', now()),
  ('mekong-riverside-homestay', 'approved', null, 'Mekong Riverside Homestay', 'River view · Boat trips', 'Wake up to the sound of the Mekong. This riverside home in Kampong Cham offers a private room, sunset boat rides, and fresh river fish for dinner.', array['https://images.unsplash.com/photo-1634623391440-eee532636511?auto=format&fit=crop&w=1600&q=82', 'https://images.unsplash.com/photo-1672833474987-d50e626b7f3d?auto=format&fit=crop&w=1600&q=82', 'https://images.unsplash.com/photo-1645791973923-0a64f698d6ef?auto=format&fit=crop&w=1600&q=82']::text[], 'https://images.unsplash.com/photo-1634623391440-eee532636511?auto=format&fit=crop&w=800&q=80', 'Kampong Cham', 'Mekong Riverbank', 'Riverside Homestay', array['Rural & Countryside', 'Riverside']::text[], 22, 'USD', 'night', 4.8, 57, 4, 3, 'Riverfront private room', 22, 'sqm', array['WiFi', 'Parking', 'Hot water', 'Kitchen access']::text[], array['Sunset boat ride', 'River fishing', 'Home-cooked meals']::text[], 'Bunthoeun Chea', 'https://images.example.com/hosts/bunthoeun-chea.jpg', now()),
  ('rice-field-homestay', 'approved', null, 'Rice Field Homestay', 'Farm experience · Open views', 'Live and work alongside a farming family in Battambang. Try your hand at planting rice, milking cows, and cooking with ingredients straight from the field.', array['https://images.unsplash.com/photo-1672833474987-d50e626b7f3d?auto=format&fit=crop&w=1600&q=82', 'https://images.unsplash.com/photo-1645791973923-0a64f698d6ef?auto=format&fit=crop&w=1600&q=82', 'https://images.unsplash.com/photo-1770850994002-718c87787ce5?auto=format&fit=crop&w=1600&q=82']::text[], 'https://images.unsplash.com/photo-1672833474987-d50e626b7f3d?auto=format&fit=crop&w=800&q=80', 'Battambang', 'Rice Field Country', 'Farm Homestay', array['Rural & Countryside', 'Farm experience']::text[], 20, 'USD', 'night', 4.6, 33, 5, 4, 'Farmhouse shared room', 28, 'sqm', array['WiFi', 'Parking', 'Fan', 'Shared bathroom']::text[], array['Rice planting', 'Farm tour', 'Home-cooked meals']::text[], 'Ratanak Sor', 'https://images.example.com/hosts/ratanak-sor.jpg', now()),
  ('kampot-plantation-homestay', 'approved', null, 'Kampot Plantation Homestay', 'Pepper farm · Countryside air', 'Nestled among Kampot''s famous pepper plantations, this homestay lets you tour the farm, sample fresh pepper, and relax in the cool countryside air.', array['https://images.unsplash.com/photo-1645791973923-0a64f698d6ef?auto=format&fit=crop&w=1600&q=82', 'https://images.unsplash.com/photo-1770850994002-718c87787ce5?auto=format&fit=crop&w=1600&q=82', 'https://images.unsplash.com/photo-1774846505579-4a710ff4c5fe?auto=format&fit=crop&w=1600&q=82']::text[], 'https://images.unsplash.com/photo-1645791973923-0a64f698d6ef?auto=format&fit=crop&w=800&q=80', 'Kampot', 'Pepper Farm District', 'Plantation Homestay', array['Rural & Countryside', 'Plantation']::text[], 24, 'USD', 'night', 4.9, 62, 2, 2, 'Private garden bungalow', 20, 'sqm', array['WiFi', 'Parking', 'Hot water', 'Air conditioning']::text[], array['Pepper farm tour', 'Bike rental', 'Home-cooked meals']::text[], 'Chenda Pich', 'https://images.example.com/hosts/chenda-pich.jpg', now()),
  ('sre-ambel-community-homestay', 'approved', null, 'Sre Ambel Community Homestay', 'River visit · Community life', 'A community-run homestay along the Sre Ambel river, offering an authentic look at coastal village life with river visits and shared community meals.', array['https://images.unsplash.com/photo-1770850994002-718c87787ce5?auto=format&fit=crop&w=1600&q=82', 'https://images.unsplash.com/photo-1774846505579-4a710ff4c5fe?auto=format&fit=crop&w=1600&q=82', 'https://images.unsplash.com/photo-1628194968194-5189a8b51909?auto=format&fit=crop&w=1600&q=82']::text[], 'https://images.unsplash.com/photo-1770850994002-718c87787ce5?auto=format&fit=crop&w=800&q=80', 'Koh Kong', 'Sre Ambel River', 'Community Homestay', array['Rural & Countryside', 'Community-run']::text[], 28, 'USD', 'night', 4.5, 24, 4, 3, 'Community house private room', 24, 'sqm', array['WiFi', 'Parking', 'Fan', 'Kitchen access']::text[], array['River visit', 'Community meal', 'Fishing trip']::text[], 'Vanna Keo', 'https://images.example.com/hosts/vanna-keo.jpg', now()),
  ('phnom-penh-countryside-stay', 'approved', null, 'Phnom Penh Countryside Stay', 'Local life · Quiet escape', 'Just outside the capital, this Kandal countryside home offers a quiet escape with easy access to Phnom Penh and a genuine taste of everyday rural life.', array['https://images.unsplash.com/photo-1774846505579-4a710ff4c5fe?auto=format&fit=crop&w=1600&q=82', 'https://images.unsplash.com/photo-1628194968194-5189a8b51909?auto=format&fit=crop&w=1600&q=82', 'https://images.unsplash.com/photo-1634623391440-eee532636511?auto=format&fit=crop&w=1600&q=82']::text[], 'https://images.unsplash.com/photo-1774846505579-4a710ff4c5fe?auto=format&fit=crop&w=800&q=80', 'Kandal', 'Phnom Penh Countryside', 'Countryside Homestay', array['Rural & Countryside', 'Near capital']::text[], 19, 'USD', 'night', 4.6, 29, 3, 3, 'Private garden room', 19, 'sqm', array['WiFi', 'Parking', 'Hot water', 'Shared bathroom']::text[], array['Home-cooked meals', 'Bike rental', 'Local market visit']::text[], 'Dara Nhem', 'https://images.example.com/hosts/dara-nhem.jpg', now())
